# Generated by Django 5.2.12 on 2026-10-29 08:40

from django.db import migrations

GONE = ("CLOSED_BASE", "CANCELLED")
WAITING = ("PENDING", "NOTIFY_FAILED", "CANCELLED")


def refresh_statuses(apps, schema_editor):
    """
    Give every order the status of its albaranes.

    ---

    S140: hasta ahora la orden se quedaba siempre en "Pendiente". Misma
    regla que WorkOrderAssistance.refresh_status; las facturadas y las
    que no tienen albaranes no se tocan.
    """
    order_model = apps.get_model("budgets", "WorkOrderAssistance")
    for order in order_model.objects.exclude(status="INVOICED"):
        statuses = list(order.units.values_list("status", flat=True))
        if not statuses:
            continue
        if all(s in GONE for s in statuses):
            if "CLOSED_BASE" not in statuses:
                continue
            new = "COMPLETED"
        elif any(s not in WAITING for s in statuses):
            new = "IN_PROGRESS"
        else:
            new = "PENDING"
        if new != order.status:
            order_model.objects.filter(pk=order.pk).update(status=new)


class Migration(migrations.Migration):

    dependencies = [
        ("budgets", "0053_unit_km_steps_s140"),
    ]

    operations = [
        migrations.RunPython(refresh_statuses, migrations.RunPython.noop),
    ]
